-- Efficient Games historical Forever trainer captures (9fcae73cc74fea4f1c4f2f09df9ca811b0f893ae, CC BY 4.0).
-- Corroborated by All The Things 5.4.9 learnedAt values (1e38eaa8ab4482387b0479459772b496e30d8ca2).
DROP TEMPORARY TABLE IF EXISTS everlake_profession_ranks;
CREATE TEMPORARY TABLE everlake_profession_ranks (
    trainer INT NOT NULL, spell INT NOT NULL, npc INT NOT NULL, skill INT NOT NULL,
    old_rank INT NOT NULL, new_rank INT NOT NULL, PRIMARY KEY (trainer, spell)
);

UPDATE trainer_spell t
JOIN everlake_profession_ranks r ON r.trainer=t.TrainerId AND r.spell=t.SpellId
JOIN creature_trainer n ON n.TrainerId=r.trainer AND n.CreatureId=r.npc
SET t.ReqSkillRank=r.new_rank
WHERE t.ReqSkillLine=r.skill AND t.ReqSkillRank=r.old_rank;

DROP TEMPORARY TABLE everlake_profession_ranks;
